// TH14 synthetic training aliases (subset copied from transcribe/th14/touhou-bullets.ecl).
// Native type 8 RICE / type 9 KUNAI keep the same modern slot number.
const TH14_RICE: int = 480;
const TH14_KUNAI: int = 496;

// TH14 v1.00b th14_s4_w05 — Stage 4 道中 MainSub02 (st04.ecl.txt:1067-1089)
// 两批各 10 轮；每轮两个 10 帧点各创建 2 只 GirlA01/01b（x=±224, y=32），批间 wait(180)。
// 敌闭包 st04.ecl.txt:439-525（GirlA01/GirlA01b 的动画与掉落按统一口径省略）。
// 难度：普通 rank0=Easy … rank3=Lunatic。

const TIME_LIMIT: int = 2224;
const OPENING_BUFFER: int = 120;
const GIRL_HP: int = 60;
const BULLET_COLOR: int = 6;

// 源 481：etEx(type 0x200000 VELTIME, a=60, r=1+2*%RANDF, s=pi/2)。
// r 在发射器配置时抽样一次，同波 5 颗共享；效果进入后 60 帧沿字面角 +y 线性加速
// delta=(r-1)/60（原作同时推进逻辑标量速，本段后续不再读取它）。
xformdef RICE_VELTIME(delta: fx) {
    @120 add_speed(0fx);          // 源 480 WAIT 120（ANIM 出生阶段按统一口径省略）
    @60 set_gravity(0fx, delta);  // 源 481 VELTIME 60 帧
    set_gravity(0fx, 0fx);
}

// 源 473-483 第一群：5 颗 rice（type8, color6），固定向下扇形（etAim 1），
// 角间距 1°，速率 1。ANIM 出生退位移 position -= 4*初速 = 4px。
sub rice_shot(px: fx, py: fx, a: angle, delta: fx) {
    _ = fire(TH14_RICE, BULLET_COLOR,
             px - 4fx * cos(a), py - 4fx * sin(a),
             1fx, a, RICE_VELTIME(delta), none);
}

// 源 484-500 第二群：3 颗 kunai（type9, color6），固定向下扇形，中心 90°+RANDF2*30°，
// 角间距 45°，速率 1.5。ANIM 退位移 4*1.5 = 6px。
sub kunai_shot(px: fx, py: fx, a: angle) {
    _ = fire(TH14_KUNAI, BULLET_COLOR,
             px - 6fx * cos(a), py - 6fx * sin(a),
             1.5fx, a, none, none);
}

async sub girl_fire() {
    // 源 469 diffI(B, 3, 4, 2, 1)；源 483 门 DIFF>=1 且 A%B==0；源 503-512 间隔 25/20/15/10。
    var gate: int = 0;
    var b: int = 3;
    var interval: int = 25;
    var rank: int = global(GVAR_RANK);
    if rank == 1 { gate = 1; b = 4; interval = 20; }
    if rank == 2 { gate = 1; b = 2; interval = 15; }
    if rank == 3 { gate = 1; b = 1; interval = 10; }
    var a_count: int = 0;
    loop {
        wait(3 + rand(25));                       // 源 472 wait(3 + RAND%25)
        var u: fx = (rand(65536) as fx) / 65536;  // 源 481 %RANDF，每波一次
        var delta: fx = 2fx * u / 60;
        rice_shot($self_x, $self_y, 90deg, delta);
        rice_shot($self_x, $self_y, 89deg, delta);
        rice_shot($self_x, $self_y, 91deg, delta);
        rice_shot($self_x, $self_y, 88deg, delta);
        rice_shot($self_x, $self_y, 92deg, delta);
        if (gate == 1) && (a_count % b == 0) {
            // 源 497 %RANDF2 * 0.5235988rad = ±30°（BAM 5461），每波一次。
            var off: int = ((((rand(65536) - 32768) as fx) / 32768) * 5461fx) as int;
            var center: angle = 90deg + (off as angle);
            kunai_shot($self_x, $self_y, center);
            kunai_shot($self_x, $self_y, center - 45deg);
            kunai_shot($self_x, $self_y, center + 45deg);
        }
        a_count = a_count + 1;
        wait(interval);
    }
}

async sub girl(sign: int) {
    set_invuln(65535);
    set_hurtbox(12fx);   // 源 450 setHurtbox(24,24)：普通圆第一值×0.5
    set_hitbox(8fx);     // 源 451 setHitbox(16,16)：普通圆第一值×0.5
    spawn girl_fire();   // 源 452 @GirlA01_at2() async
    // 源 453-457：右侧 enmCreateM 子镜像=1，镜像只翻 x，故实际角为 180°-源角。
    if sign > 0 {
        move_vel(0, 22.5deg, 4fx, EASE_LINEAR);         // 源 453 pi/8, 4
        move_vel(120, -11.25deg, 3fx, EASE_QUAD_IN);    // 源 454 mode1 -pi/16, 3
        wait(120);                                      // 源 455
        move_vel(60, 11.25deg, 4fx, EASE_QUAD_OUT);     // 源 456 mode4 +pi/16, 4
    } else {
        move_vel(0, 157.5deg, 4fx, EASE_LINEAR);
        move_vel(120, 191.25deg, 3fx, EASE_QUAD_IN);
        wait(120);
        move_vel(60, 168.75deg, 4fx, EASE_QUAD_OUT);
    }
    loop { wait(1000); }  // 源 458-461
}

async sub pattern() {
    wait(OPENING_BUFFER);
    for batch in 0..2 {          // 源 1067/1079 的 $A、$B 各 10 轮
        for i in 0..10 {
            _ = spawn_enemy(-224fx, 32fx, GIRL_HP, 0, 0, 0, girl(1));  // 源 1070/1082 GirlA01b
            _ = spawn_enemy(224fx, 32fx, GIRL_HP, 0, 0, 0, girl(-1));  // 源 1071/1083 GirlA01(M)
            wait(10);
            _ = spawn_enemy(-224fx, 32fx, GIRL_HP, 0, 0, 0, girl(1));  // 源 1073/1085 GirlA01
            _ = spawn_enemy(224fx, 32fx, GIRL_HP, 0, 0, 0, girl(-1));  // 源 1074/1086 GirlA01b(M)
            wait(10);
        }
        if batch == 0 { wait(180); }  // 源 1078
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
